def populate_catalog_data(apps, schema_editor):
    Category = apps.get_model('products', 'Category')
    Product = apps.get_model('products', 'Product')
    category_names = {
        'MILK': 'Milk',
        'GHEE': 'Ghee',
        'BUTTER': 'Butter',
        'CHEESE': 'Cheese',
        'YOGURT': 'Yogurt',
        'CREAM': 'Cream',
        'PANEER': 'Paneer',
        'LASSI': 'Lassi',
        'KHOYA': 'Khoya',
        'MILK_POWDER': 'Milk Powder',
        'fresh_dairy': 'Fresh Dairy',
        'milk_products': 'Milk Products',
        'yogurt_products': 'Yogurt Products',
        'cheese_products': 'Cheese Products',
        'butter_products': 'Butter & Spreads',
        'cream_products': 'Cream Products',
        'traditional_dairy': 'Traditional Dairy',
        'frozen_dairy': 'Frozen Dairy',
        'desserts': 'Dairy Desserts',
    }
    for old_name, new_name in category_names.items():
        Category.objects.filter(name=old_name).update(name=new_name)

    from django.utils.text import slugify

    used_slugs = set()
    for product in Product.objects.all().only('pk', 'name').order_by('pk').iterator():
        base_slug = slugify(product.name) or 'product'
        slug = base_slug
        suffix = 2
        while slug in used_slugs:
            slug = f'{base_slug}-{suffix}'
            suffix += 1
        used_slugs.add(slug)
        Product.objects.filter(pk=product.pk).update(slug=slug)


def merge_duplicate_cart_rows(apps, schema_editor):
    Cart = apps.get_model('products', 'Cart')
    duplicates = (
        Cart.objects.values('customer_id', 'product_id')
        .annotate(total_quantity=Sum('quantity'))
        .filter(total_quantity__gt=0)
    )
    for group in duplicates.iterator():
        rows = list(
            Cart.objects.filter(
                customer_id=group['customer_id'],
                product_id=group['product_id'],
            ).order_by('pk')
        )
        if len(rows) > 1:
            rows[0].quantity = min(group['total_quantity'], 10)
            rows[0].save(update_fields=['quantity'])
            Cart.objects.filter(pk__in=[row.pk for row in rows[1:]]).delete()


def migrate_legacy_orders(apps, schema_editor):
    LegacyOrder = apps.get_model('products', 'Orders')
    Customer = apps.get_model('accounts', 'Customer')
    Transaction = apps.get_model('transactions', 'Transaction')
    TransactionItem = apps.get_model('transactions', 'TransactionItem')
    Product = apps.get_model('products', 'Product')
    order_statuses = {
        'pending': 'placed',
        'processing': 'processing',
        'shipped': 'shipped',
        'delivered': 'delivered',
        'cancelled': 'cancelled',
    }

    for order in LegacyOrder.objects.all().order_by('pk').iterator():
        customer = Customer.objects.select_related('user').get(pk=order.customer_id)
        product = Product.objects.get(pk=order.product_id)
        transaction = Transaction.objects.create(
            customer=customer,
            total_amount=product.price * order.quantity,
            currency='PKR',
            payment_method='cod',
            payment_status='pending',
            order_status=order_statuses.get(order.status.lower(), 'placed'),
            shipping_name=customer.name or customer.user.username,
            shipping_phone=customer.mobile,
            shipping_address=customer.locality or 'Address not provided',
            shipping_city=customer.city or 'Not provided',
        )
        Transaction.objects.filter(pk=transaction.pk).update(created_at=order.order_date)
        TransactionItem.objects.create(
            transaction=transaction,
            product=product,
            product_name=product.name,
            quantity=order.quantity,
            unit_price=product.price,
        )


